// === Tab: shaderParkCode.js ===

// All the code below is javascript that's compiled into a shader
// Find more info at www.shaderpark.com

const shaderParkCode =  `
  let click = input();
	let buttonHover = input();

  function fbm(p, offset, rings) {
    return vec3(
      nsin(noise(p) * rings),
      nsin(noise(p+offset) * rings),
      nsin(noise(p+offset*2) * rings),
    )
  }

	let nscale = 1.2
	let nAmplitude = .02
	let hueOffset = .03
	let rings = 4
	let mixAmt = 1 - click

	let s = getSpace();
	let samplePos = s * nscale + vec3(0, 0, time) * .2
	let col = fbm(samplePos, hueOffset, rings);
	col = pow(col, vec3(4.2));
	color(col);
	rotateX(mouse.y*.1)
	rotateY(mouse.x*.1)
	shape(() => {
		rotateX(PI/2);
		torus(.8, .5);
		sphere(.28);
		mixGeo(mixAmt);
		mirrorN(3, .1);
		shape(() => {
			rotateX(time*.1)
			rotateZ(time*.1)
			boxFrame(vec3(.1), .005);
			sphere(.05);
		})()
	})();
`;

